#!/usr/bin/env node
// Gets Obsidian onto the debug port with the slot vault open, then takes the vault lock.
//   node launch.mjs [--slot N] [--port 9222] [--worktree <path>]
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { DEFAULT_PORT, OBSIDIAN_APP, acquireLock, parseArgs, resolveWorktree } from "./config.mjs";
import { doctor, obsidianPids, probePort } from "./doctor.mjs";
import { connect } from "./driver.mjs";

const run = (cmd, args) => {
  const res = spawnSync(cmd, args, { encoding: "utf8" });
  if (res.status !== 0) throw new Error(`${cmd} ${args.join(" ")} failed: ${res.stderr.trim()}`);
};

const until = async (check, { timeout, label }) => {
  const deadline = Date.now() + timeout;
  while (!(await check())) {
    if (Date.now() > deadline) throw new Error(`timeout: ${label}`);
    await new Promise((r) => setTimeout(r, 200));
  }
};

// Quit and relaunch are separate process calls; the auto-mode classifier blocks them combined.
const quitObsidian = async () => {
  run("osascript", ["-e", 'quit app "Obsidian"']);
  await until(() => obsidianPids().length === 0, { timeout: 20000, label: "Obsidian exit" });
};

const launchWithPort = async (port) => {
  run("open", ["-na", OBSIDIAN_APP, "--args", `--remote-debugging-port=${port}`]);
  await until(() => probePort(port), { timeout: 30000, label: `CDP port ${port}` });
};

export const launch = async ({ worktree, slot, port = DEFAULT_PORT }) => {
  const started = Date.now();
  const report = await doctor({ worktree, slot, port });
  if (!report.ok) throw Object.assign(new Error(report.error), { exitCode: 2 });
  const { vault, branch, obsidian } = report;

  let action = "attach";
  if (obsidian.state === "running-without-port") {
    action = "relaunch";
    await quitObsidian();
    await launchWithPort(port);
  } else if (obsidian.state === "not-running") {
    action = "launch";
    await launchWithPort(port);
  }

  run("open", [`obsidian://open?path=${encodeURIComponent(vault.root)}`]);
  const client = await connect({ port, root: vault.root, timeout: 45000 });
  acquireLock({ lockFile: vault.lockFile, branch });
  return { client, vault, branch, action, obsidianBefore: obsidian.state, ms: Date.now() - started };
};

