#!/usr/bin/env node
// Read-only: resolves the vault slot, checks its lock and reports Obsidian's state as JSON.
//   node doctor.mjs [--slot N] [--port 9222] [--worktree <path>]
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import {
  DEFAULT_PORT,
  parseArgs,
  readLock,
  resolveBranch,
  resolveSlot,
  resolveWorktree,
} from "./config.mjs";

export const probePort = async (port) => {
  try {
    const res = await fetch(`http://127.0.0.1:${port}/json/version`, {
      signal: AbortSignal.timeout(1000),
    });
    return res.ok ? await res.json() : null;
  } catch {
    return null;
  }
};

// Exact name match: helpers are "Obsidian Helper (...)", the main process is "Obsidian".
export const obsidianPids = () => {
  try {
    return execFileSync("pgrep", ["-x", "Obsidian"], { encoding: "utf8" })
      .trim()
      .split("\n")
      .filter(Boolean)
      .map(Number);
  } catch {
    return [];
  }
};

export const detectObsidian = async (port) => {
  const version = await probePort(port);
  if (version) return { state: "running-with-port", port, browser: version.Browser };
  const pids = obsidianPids();
  return pids.length ? { state: "running-without-port", pids } : { state: "not-running" };
};

export const doctor = async ({ worktree, slot, port = DEFAULT_PORT }) => {
  const branch = resolveBranch(worktree);
  const vault = resolveSlot({ worktree, slot });
  const lock = readLock(vault.lockFile);
  const obsidian = await detectObsidian(port);
  const blocked = Boolean(lock?.alive && !lock.self);
  return {
    ok: !blocked,
    branch,
    worktree,
    vault,
    lock,
    obsidian,
    ...(blocked && {
      error:
        `Vault ${vault.name} is being driven by pid ${lock.pid} on branch ${lock.branch} ` +
        `since ${lock.startedAt}. Wait for that run, or ask Trang before claiming another vault ` +
        `with obsidian-vault (vault.mjs claim --take <vault>).`,
    }),
  };
};

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseArgs(process.argv.slice(2));
  const report = await doctor({
    worktree: args.worktree ?? resolveWorktree(),
    slot: args.slot,
    port: Number(args.port ?? DEFAULT_PORT),
  }).catch((error) => {
    console.error(error.message);
    process.exit(error.exitCode ?? 1);
  });
  console.log(JSON.stringify(report, null, 2));
  if (!report.ok) {
    console.error(`\n${report.error}`);
    process.exit(2);
  }
}

