#!/usr/bin/env node
// One-shot build into the slot vault's plugin dir, marker preflight, plugin reload.
//   node deliver.mjs --marker "<string unique to this change>" [--slot N] [--port 9222]   (no --slot: this worktree's leased vault)
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { DEFAULT_PORT, parseArgs, resolveSlot, resolveWorktree } from "./config.mjs";
import { connect } from "./driver.mjs";
import { scanWatchers } from "../../obsidian-vault/scripts/vault.mjs";

export const bundleHash = (pluginDir) => {
  const file = path.join(pluginDir, "main.js");
  return existsSync(file) ? createHash("sha1").update(readFileSync(file)).digest("hex") : null;
};

// Only other worktrees' apps/obsidian watchers that mirror into this vault can overwrite the build.
export const findCompetingWatchers = ({ worktree, vault }) =>
  scanWatchers([vault])
    .filter((w) => w.vaults.length && w.worktree !== worktree)
    .map((w) => `pids ${w.pids.join(",")} from ${w.worktree}`);

export const build = ({ worktree, pluginDir }) => {
  const appDir = path.join(worktree, "apps", "obsidian");
  const tsx = path.join(appDir, "node_modules", ".bin", "tsx");
  const res = spawnSync(existsSync(tsx) ? tsx : "npx", existsSync(tsx) ? ["scripts/build.ts"] : ["tsx", "scripts/build.ts"], {
    cwd: appDir,
    env: { ...process.env, OBSIDIAN_PLUGIN_PATH: pluginDir },
    encoding: "utf8",
  });
  const log = `${res.stdout}${res.stderr}`;
  if (res.status !== 0 || !log.includes(`mirrored to ${pluginDir}`))
    throw new Error(`build failed or did not mirror to ${pluginDir}:\n${log.slice(-2000)}`);
};

export const checkMarker = ({ pluginDir, marker }) => {
  const file = path.join(pluginDir, "main.js");
  if (!existsSync(file)) throw new Error(`no bundle at ${file}`);
  if (!readFileSync(file, "utf8").includes(marker))
    throw Object.assign(
      new Error(
        `PREFLIGHT FAIL: ${file} does not contain ${JSON.stringify(marker)}. Either the marker ` +
          `is not in this change's bundled code, or another worktree's watcher overwrote the build.`,
      ),
      { exitCode: 3 },
    );
};

export const deliver = async ({ worktree, vault, client, marker, skipBuild = false }) => {
  if (!marker) throw new Error("--marker is required: a string only this change's bundle contains");
  const started = Date.now();
  const watchers = findCompetingWatchers({ worktree, vault });
  if (!skipBuild) build({ worktree, pluginDir: vault.pluginDir });
  const buildMs = Date.now() - started;
  checkMarker({ pluginDir: vault.pluginDir, marker });
  const pluginId = await client.reloadPlugin(vault);
  checkMarker({ pluginDir: vault.pluginDir, marker });
  return { pluginId, watchers, bundleSha: bundleHash(vault.pluginDir), buildMs, ms: Date.now() - started };
};

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseArgs(process.argv.slice(2));
  const worktree = args.worktree ?? resolveWorktree();
  let client;
  try {
    const vault = resolveSlot({ worktree, slot: args.slot });
    client = await connect({ port: Number(args.port ?? DEFAULT_PORT), root: vault.root, timeout: 5000 });
    const result = await deliver({ worktree, vault, client, marker: args.marker, skipBuild: !!args["skip-build"] });
    for (const w of result.watchers) console.warn(`WARN competing watcher: ${w}`);
    console.log(JSON.stringify(result));
  } catch (error) {
    console.error(error.message);
    process.exitCode = error.exitCode ?? 1;
  } finally {
    client?.close();
  }
}
