// ENG-2114 "insert active search result as a link at cursor", as scenario modules.
//   run.mjs --marker "insert link at cursor" --scenario examples/insert-link-at-cursor.mjs
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`; // contenteditable chips input, not an <input>
const SCRATCH = "insert-link-scratch.md";
const ORIGINAL = "before| after\n";

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input rendered" });
};

const footerLabels = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(`${MODAL} .dg-search-footer-action`)}))
    .map((el) => el.textContent.trim());`);

const linkConfig = ({ client }) =>
  client.evaluate(`return { useMarkdownLinks: app.vault.getConfig("useMarkdownLinks"),
    newLinkFormat: app.vault.getConfig("newLinkFormat") };`);

const setLinkConfig = ({ client, json }, cfg) =>
  client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${json(cfg.useMarkdownLinks)});
    app.vault.setConfig("newLinkFormat", ${json(cfg.newLinkFormat)}); return true;`);

// A discourse node (has nodeTypeId) outside _verify, so the search has something to find.
const nodeTitle = ({ client }) =>
  client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && app.metadataCache.getFileCache(f)?.frontmatter?.nodeTypeId)
    ?.basename;`);

const openScratchAtCol6 = async (ctx) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(SCRATCH, ORIGINAL);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    leaf.view.editor.focus();
    leaf.view.editor.setCursor({ line: 0, ch: 6 });
    return true;
  })();`);
  return p;
};

const insertScenario = ({ name, useMarkdownLinks, newLinkFormat, pattern }) => ({
  name,
  input: `useMarkdownLinks=${useMarkdownLinks}, newLinkFormat=${newLinkFormat}; cursor at col 6; type 4 chars; Cmd+Enter`,
  expected: `modal closes; ${useMarkdownLinks ? "[text](path)" : "[[link]]"} inserted at col 6; cursor after it`,
  setup: async (ctx) => {
    const saved = await linkConfig(ctx);
    await setLinkConfig(ctx, { useMarkdownLinks, newLinkFormat });
    return { saved, title: await nodeTitle(ctx) };
  },
  run: async (ctx, { title }) => {
    const { client, json } = ctx;
    const p = await openScratchAtCol6(ctx);
    await openSearch(ctx);
    const labels = await footerLabels(ctx);
    await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
    await client.typeText(title.slice(0, 4));
    await client.waitFor(`document.querySelectorAll(${json(`${MODAL} [role="option"]`)}).length > 0`, {
      label: "results rendered",
    });
    await client.key({ key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13, modifiers: 4 });
    await client.waitFor(`!document.querySelector(${json(MODAL)})`, { label: "modal closed" });
    // Saves are debounced: poll the file instead of reading once.
    const file = `app.vault.getAbstractFileByPath(${json(p)})`;
    await client.waitFor(`app.vault.read(${file}).then((t) => t !== ${json(ORIGINAL)})`, { label: "note written" });
    return client.evaluate(`return app.vault.read(${file}).then((text) => ({
      labels: ${json(labels)}, text, cursor: app.workspace.activeLeaf.view.editor.getCursor(),
      path: app.workspace.activeLeaf.view.file.path }));`);
  },
  expect: (a) => {
    const inserted = a.text.slice(6, a.text.length - " after\n".length).replace(/\|$/, "");
    const pass =
      a.labels.some((l) => l.includes("insert link at cursor")) &&
      a.text.startsWith("before") && a.text.endsWith(" after\n") &&
      pattern.test(inserted.trim()) && a.cursor.line === 0 && a.cursor.ch > 6 && a.path.endsWith(SCRATCH);
    return { pass, actual: `inserted ${inserted.trim()} → cursor ch ${a.cursor.ch}` };
  },
  teardown: (ctx, state) => state && setLinkConfig(ctx, state.saved),
});

export default [
